Scripts.OnEnter:
if(canaccessvalue(self.data.unitID)) then GameTooltip:SetOwner(self, "ANCHOR_RIGHT") GameTooltip:SetUnit(self.data.unitID)
if(self.data.unitID) then if(self.data.index) then local name, rank, subgroup, level, class, fileName, zone, online, isDead, role, isML, combatRole = GetRaidRosterInfo(self.data.index) --ONLY WORKS WHEN IN GROUP
if(rank == 2 ) then GameTooltip_AddBlankLineToTooltip(GameTooltip) GameTooltip:AddLine("Rank: " .. RAID_LEADER)
elseif(rank == 1 ) then GameTooltip_AddBlankLineToTooltip(GameTooltip) GameTooltip:AddLine("Rank: " .. RAID_ASSISTANT)
else if(role ~= nil) then GameTooltip_AddBlankLineToTooltip(GameTooltip)
if (role == "MAINTANK" ) then GameTooltip:AddLine("Raid role: " .. MAIN_TANK); elseif (role == "MAINASSIST" ) then GameTooltip:AddLine("Raid role: " .. MAIN_ASSIST); end end end end
if(self.data.keystone) then GameTooltip_AddBlankLineToTooltip(GameTooltip) GameTooltip:AddLine("Keystone: +" .. self.data.keylevel .. " " .. self.data.keyname)
end
if(self.data.progressTooltipData) then GameTooltip_AddBlankLineToTooltip(GameTooltip) GameTooltip:AddLine(self.data.progressTooltipData)
end
if(self.data.hasWeaponEnchant) then GameTooltip_AddBlankLineToTooltip(GameTooltip) GameTooltip:AddLine(WrapTextInColorCode("Weapon enchanted", "FF00FF00"))
elseif(self.data.hasWeaponEnchant == false) then GameTooltip_AddBlankLineToTooltip(GameTooltip) GameTooltip:AddLine(WrapTextInColorCode("Weapon not enchanted", "FFFF0000"))
end
if(self.data.missingGems) then if(#self.data.missingGems > 0) then local missingGems = ""
for k, v in ipairs(self.data.missingGems) do missingGems = missingGems .. v .. " "
end
GameTooltip_AddBlankLineToTooltip(GameTooltip) GameTooltip:AddLine(WrapTextInColorCode("Unsocketed slots: " .. missingGems, "FFFF0000")) else GameTooltip_AddBlankLineToTooltip(GameTooltip) GameTooltip:AddLine(WrapTextInColorCode("All sockets filled", "FF00FF00"))
end end
if(self.data.missingEnchants) then if(#self.data.missingEnchants > 0) then local missingEnchants = ""
for k, v in ipairs(self.data.missingEnchants) do missingEnchants = missingEnchants .. v .. " "
end
GameTooltip_AddBlankLineToTooltip(GameTooltip) GameTooltip:AddLine(WrapTextInColorCode("Unenchanted slots: " .. missingEnchants, "FFFF0000")) else GameTooltip_AddBlankLineToTooltip(GameTooltip) GameTooltip:AddLine(WrapTextInColorCode("Fully enchanted", "FF00FF00"))
end end
if(self.data.online) then GameTooltip_AddBlankLineToTooltip(GameTooltip)
if(UnitIsAFK(self.data.unitID)) then GameTooltip:AddLine("Player is afk")
elseif(UnitIsDND(self.data.unitID)) then GameTooltip:AddLine("Player is set to \'Do not disturb\'")
else GameTooltip:AddLine("Player is online")
end else GameTooltip:AddLine("Player is offline")
end
GameTooltip:Show() end end

Scripts.OnClick:
if(canaccessvalue(self.data.unitID)) then
    if(button == "RightButton") then
        local type = IsInRaid() and "raid" or IsInGroup() and "party" or "player"

        contextData =
        {
            unit = self.data.unitID,
            name = self.data.fullName;
        };

        UnitPopup_OpenMenu("MIOG_" .. strupper(type), contextData);
    end
end
